package com.example.domain.model.i18n

internal object DuaPt5 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_q_sami_na_munadiyan" to DuaText("Ouvimos o chamado à fé", "Nosso Senhor, ouvimos um chamador convocar à fé dizendo: 'Crede em vosso Senhor', e cremos. Nosso Senhor, perdoa-nos nossos pecados, apaga nossos erros e faze-nos morrer com os virtuosos.", "Uma súplica pela fé e por morrer entre os virtuosos.", "Uma súplica pelo perdão e um bom fim."),
        "dua_q_sawa_as_sabil" to DuaText("Súplica de Musa (AS) — Guia-me ao caminho reto", "Talvez meu Senhor me guie ao caminho reto.", "Ao empreender uma nova viagem ou um caminho desconhecido.", "Musa (AS) disse isso ao se voltar para Madyan."),
        "dua_q_sulaiman_awzini" to DuaText("Súplica de Sulayman (AS) pela gratidão", "Meu Senhor, permite-me ser grato por Teu favor com que me agraciaste, a mim e a meus pais, e fazer boas obras que Te agradem, e faze-me entrar, por Tua misericórdia, entre Teus servos virtuosos.", "Pela capacidade de ser grato pelos favores.", "A súplica de gratidão de Sulayman (AS)."),
        "dua_q_tawaffana_muslimin" to DuaText("Paciência e morte como muçulmanos", "Nosso Senhor, derrama sobre nós a paciência e faze-nos morrer submissos.", "A súplica dos magos do Faraó quando creram.", "Paciência na provação e um bom fim na fé."),
        "dua_q_ufawwidu_amri" to DuaText("Confio meu assunto a Allah", "E confio meu assunto a Allah. Certamente, Allah observa perfeitamente Seus servos.", "Quando as pessoas se opõem a você e é preciso confiar em Allah.", "As palavras do crente do povo do Faraó; Allah o protegeu depois de seus maus planos."),
        "dua_q_wasita_kulla_shay" to DuaText("Súplica dos anjos portadores do Trono", "Nosso Senhor, Tu abarcas todas as coisas com Tua misericórdia e Teu conhecimento; perdoa, pois, aos que se arrependem e seguem Teu caminho, e preserva-os do castigo do Inferno.", "Os anjos portadores do Trono fazem esta súplica pelos crentes.", "Recitá-la com a intenção de ser incluído na súplica dos anjos."),
        "dua_qadarullah" to DuaText("É o decreto de Allah", "É o decreto de Allah, e Ele fez o que quis.", "Quando acontece algo desagradável, em vez de dizer 'se ao menos'.", "'Se ao menos' abre a porta a Satanás."),
        "dua_rabba_jibrail" to DuaText("Guia-me nos assuntos controversos", "Ó Allah, Senhor de Jibril, Mikail e Israfil, Criador dos céus e da terra, Conhecedor do invisível e do visível! Tu julgarás entre Teus servos naquilo em que discordavam. Guia-me por Tua permissão à verdade naquilo que foi objeto de divergência. Certamente, Tu guias quem queres ao caminho reto.", "No início do tahajjud — para ser guiado à verdade em caso de discordância.", "O Profeta ﷺ começava sua oração noturna com esta súplica."),
        "dua_rabbana_hab_lana_rahmah" to DuaText("Orientação em nosso assunto (Gente da Caverna)", "Nosso Senhor, concede-nos de Tua parte uma misericórdia e assegura-nos uma conduta reta em nosso assunto.", "A súplica da Gente da Caverna.", "Para ser guiado nas decisões e situações difíceis."),
        "dua_rabbana_innana_amanna" to DuaText("Perdão e proteção contra o Fogo", "Nosso Senhor, cremos, perdoa-nos então nossos pecados e protege-nos do castigo do Fogo.", "Súplica alcorânica.", "Uma súplica mencionada entre as qualidades dos piedosos."),
        "dua_rabbi_ainni" to DuaText("Meu Senhor, ajuda-me e não contra mim", "Meu Senhor, ajuda-me e não ajudes os outros contra mim, concede-me a vitória e não a concedas aos outros contra mim, planeja em meu favor e não contra mim, guia-me e facilita-me a orientação, e ajuda-me contra quem me faz mal.", "Uma súplica completa do Profeta ﷺ (primeira parte).", "Uma súplica que reúne toda forma de ajuda na religião e neste mundo."),
        "dua_rabbighfir_tub_alayya" to DuaText("Perdoa-me e aceita meu arrependimento", "Meu Senhor, perdoa-me e aceita meu arrependimento. Certamente, Tu és o Aceitador do arrependimento, o Misericordioso.", "Cem vezes em uma única sessão — a prática do Profeta ﷺ.", "Os Companheiros contaram o Profeta ﷺ dizer isso cem vezes em uma única sessão."),
        "dua_rafiq_ala" to DuaText("Súplica do moribundo", "Ó Allah, perdoa-me, tem misericórdia de mim e junta-me ao Companheiro Supremo.", "A última súplica do Profeta ﷺ — para o próprio doente.", "O Profeta ﷺ fez esta súplica no momento de seu falecimento."),
        "dua_rahmataka_arju" to DuaText("É Tua misericórdia que espero", "Ó Allah, é Tua misericórdia que espero, não me abandones então a mim mesmo, nem que seja por um piscar de olhos, e corrige todos os meus assuntos. Não há divindade senão Tu.", "A súplica de quem está em aflição (Da'awat al-makrub).", "O Profeta ﷺ a chamava de súplica de quem está em aflição."),
        "dua_rain" to DuaText("Quando chove", "Ó Allah, (faze que seja) uma chuva benéfica.", "Quando chove.", "A chuva é um momento em que as súplicas são atendidas."),
        "dua_reply_ahl_kitab_salam" to DuaText("Responder ao salam da Gente do Livro", "E sobre vós.", "Quando a Gente do Livro saúda com o salam.", "A instrução do Profeta ﷺ."),
        "dua_rising_ruku_mil" to DuaText("Depois do ruku — Louvor que enche os céus", "Nosso Senhor, a Ti todo o louvor, enchendo os céus, enchendo a terra, e enchendo tudo o que Tu quiseres além disso.", "Ao se levantar do ruku, com 'Rabbana lakal-hamd'.", "O Profeta ﷺ dizia isso ao se levantar do ruku."),
        "dua_rooster_donkey" to DuaText("Ao ouvir um galo ou um burro", "Ó Allah, peço-Te de Tua graça (galo). — Busco refúgio em Allah contra Satanás, o amaldiçoado (burro).", "Ao ouvir um galo cantar, pedir o favor de Allah; ao ouvir um burro zurrar, buscar refúgio contra Satanás.", "O galo vê um anjo e o burro vê um demônio."),
        "dua_ruku_laka_raka_tu" to DuaText("No ruku — A Ti me inclinei", "Ó Allah, a Ti me inclinei, em Ti cri e a Ti me submeti. Minha audição, minha visão, minha mente, meus ossos e meus tendões se humilharam diante de Ti.", "No ruku (especialmente nas orações voluntárias).", "O Profeta ﷺ o recitava no ruku."),
        "dua_ruku_sujood_subhanaka" to DuaText("Glória a Ti, nosso Senhor — Perdoa-me", "Glória a Ti, ó Allah, nosso Senhor, e louvor a Ti. Ó Allah, perdoa-me.", "No ruku e no sujud.", "Aisha (RA): o Profeta ﷺ dizia isso frequentemente no ruku e no sujud."),
        "dua_sabr" to DuaText("Pela paciência e firmeza", "Nosso Senhor, derrama sobre nós a paciência, firma nossos passos e concede-nos a vitória sobre os descrentes.", "Em tempos de provação e confronto.", "A súplica do exército de Talut."),
        "dua_safa_marwa" to DuaText("Em Safa e Marwa", "Ninguém tem o direito de ser adorado senão Allah, Único, sem associado. D'Ele é o domínio, a Ele pertence o louvor, e Ele é capaz de todas as coisas. Ninguém tem o direito de ser adorado senão Allah Único; Ele cumpriu Sua promessa, socorreu Seu servo e venceu sozinho os coligados.", "Ao subir em Safa e voltar-se para a Qibla (três vezes).", "O dhikr do Profeta ﷺ em Safa e Marwa."),
        "dua_sajdah_tilawah" to DuaText("A prostração de recitação", "Meu rosto se prostrou diante Daquele que o criou, que lhe deu a audição e a visão por Seu poder e Sua força.", "Na prostração de recitação.", "O Profeta ﷺ dizia isso na prostração de recitação, à noite."),
        "dua_seeing_clouds" to DuaText("Ao ver nuvens escuras", "Ó Allah, busco refúgio em Ti contra seu mal.", "Ao ver nuvens escuras no céu; se chover, dizer 'Allahumma sayyiban nafi'a'.", "Ao ver nuvens, o Profeta ﷺ interrompia o que fazia para esta súplica."),
        "dua_seeing_muslim_smile" to DuaText("A saudação (Salam)", "Que a paz esteja sobre vós, assim como a misericórdia de Allah e Suas bênçãos.", "Ao encontrar um muçulmano.", "Dizer o salam completo vale trinta boas ações."),
        "dua_sell_buy_debt_repaid" to DuaText("Ao quitar uma dívida", "Que Allah te abençoe em tua família e teus bens.", "Para o credor ao receber o pagamento de uma dívida.", "A justa contrapartida de um empréstimo é a gratidão e o pagamento."),
        "dua_shaitan_hamazat" to DuaText("Refúgio contra as sugestões dos demônios", "Meu Senhor, busco refúgio em Ti contra as sugestões dos demônios, e busco refúgio em Ti, meu Senhor, para que não se aproximem de mim.", "Proteção contra os sussurros satânicos.", "Uma súplica alcorânica de proteção."),
        "dua_sharri_ma_amiltu" to DuaText("Refúgio contra o mal de meus atos", "Ó Allah, busco refúgio em Ti contra o mal do que fiz e o mal do que não fiz.", "Uma súplica do Profeta ﷺ, segundo Aisha (RA).", "Proteção contra as consequências do que foi feito e do que foi omitido."),
        "dua_sharri_sami" to DuaText("Refúgio contra o mal de meus sentidos", "Ó Allah, busco refúgio em Ti contra o mal de minha audição, o mal de minha visão, o mal de minha língua, o mal de meu coração e o mal de meu desejo.", "Ensinada a Shakal ibn Humayd (RA).", "Uma súplica para proteger os membros e a alma do pecado."),
        "dua_shirk_protection" to DuaText("Proteção contra o politeísmo oculto", "Ó Allah, busco refúgio em Ti contra associar-Te algo conscientemente, e peço-Te perdão pelo que faço sem saber.", "Para se preservar da ostentação e do shirk oculto.", "O shirk oculto é mais discreto que o passo de uma formiga negra."),
        "dua_slaughtering" to DuaText("Ao abater um animal", "Em nome de Allah, e Allah é o Maior.", "No sacrifício ou abate de um animal.", "O Profeta ﷺ dizia o Bismillah e o takbir no momento do sacrifício."),
        "dua_sleep_atamana" to DuaText("Gratidão antes de dormir", "Louvado seja Allah que nos alimentou, saciou nossa sede, nos supriu e nos abrigou. Quantos não têm quem os supra ou os abrigue.", "Ao ir dormir.", "O Profeta ﷺ dizia isso ao ir dormir."),
        "dua_sleep_fear" to DuaText("Em caso de medo ou inquietação ao dormir", "Busco refúgio nas palavras perfeitas de Allah contra Sua ira e Seu castigo, contra o mal de Seus servos, e contra as sugestões dos demônios e sua vinda a mim.", "Em caso de medo ou inquietação durante o sono.", "Fazendo isso, nada poderá prejudicá-lo."),
        "dua_sleep_khalaqta_nafsi" to DuaText("Tu criaste minha alma", "Ó Allah, Tu criaste minha alma e a retomarás. Sua morte e sua vida Te pertencem. Se a mantiveres viva, protege-a, e se a fizeres morrer, perdoa-lhe. Ó Allah, peço-Te o bem-estar.", "Antes de dormir — relatado por Ibn Umar (RA).", "O Profeta ﷺ recomendava dizer isso ao deitar."),
        "dua_sleep_rabbas_samawat" to DuaText("Senhor dos céus — Quita nossa dívida", "Ó Allah, Senhor dos céus, da terra e do Trono imenso, nosso Senhor e Senhor de todas as coisas, Fendedor do grão e do caroço, Revelador da Torá, do Evangelho e do Discernimento! Busco refúgio em Ti contra o mal de tudo o que Tu seguras pela testa. Ó Allah, Tu és o Primeiro, nada há antes de Ti; Tu és o Último, nada há depois de Ti; Tu és o Aparente, nada há acima de Ti; Tu és o Oculto, nada Te é oculto. Quita nossa dívida e liberta-nos da pobreza.", "Antes de dormir, deitado sobre o lado direito — ensinada a Fátima (RA).", "Uma súplica para ser aliviado da dívida e das dificuldades."),
        "dua_sleep_wadatu_janbi" to DuaText("Em Teu nome me deito", "Em Teu nome, meu Senhor, deito meu flanco e em Teu nome me levanto. Se tomares minha alma, tem misericórdia dela, e se a libertares, protege-a como proteges Teus servos virtuosos.", "Depois de sacudir a cama e deitar-se.", "Confiar sua alma a Allah antes de dormir."),
        "dua_sneezing" to DuaText("O espirro", "Louvado seja Allah. — Que Allah tenha misericórdia de ti. — Que Allah te guie e corrija teu estado.", "Ao espirrar, o ouvinte diz 'Yarhamukallah', depois quem espirrou responde.", "É um dos direitos de um muçulmano sobre outro muçulmano."),
        "dua_something_liked" to DuaText("Ver algo admirável (contra o mau-olhado)", "O que Allah quis. Ó Allah, abençoa-o.", "Ao ver algo admirável em alguém, invocar a bênção.", "Invocar a bênção protege do mau-olhado."),
        "dua_subbuhun_quddus" to DuaText("Subbuhun Quddus (ruku e sujud)", "(Allah é) O Muito Glorioso, O Muito Santo, Senhor dos anjos e do Espírito (Jibril).", "No ruku e no sujud.", "O Profeta ﷺ o recitava no ruku e no sujud."),
        "dua_sujood_dhanbi_kullah" to DuaText("Em prostração: perdoa todos os meus pecados", "Ó Allah, perdoa-me todos os meus pecados — os pequenos e os grandes, os primeiros e os últimos, os visíveis e os ocultos.", "Em sujud.", "A prostração é um momento em que as súplicas são atendidas."),
        "dua_sujood_laka_sajadtu" to DuaText("Em sujud — A Ti me prostrei", "Ó Allah, a Ti me prostrei, em Ti cri e a Ti me submeti. Meu rosto se prostrou diante Daquele que o criou, moldou, e que lhe deu a audição e a visão. Bendito seja Allah, o melhor dos criadores.", "Em sujud (especialmente nas orações voluntárias).", "O Profeta ﷺ o recitava em sujud."),
        "dua_sujood_ridaka" to DuaText("Refúgio em Teu agrado", "Ó Allah, busco refúgio em Teu agrado contra Tua ira, em Teu perdão contra Teu castigo, e busco refúgio em Ti contra Ti. Não saberia louvar-Te em Tua justa medida; Tu és como Te louvaste a Ti mesmo.", "Em sujud — Aisha (RA) ouviu o Profeta ﷺ dizer isso.", "Uma súplica de prostração do Profeta ﷺ."),
        "dua_tahajjud_nur" to DuaText("Súplica de abertura do Tahajjud", "Ó Allah, a Ti o louvor; Tu és o Sustentáculo dos céus, da terra e do que neles há. A Ti o louvor; Tu és a Luz dos céus, da terra e do que neles há. A Ti o louvor; Tu és a Verdade, Tua promessa é verdadeira, Teu encontro é verdadeiro, Tua palavra é verdadeira, o Paraíso é verdadeiro, o Inferno é verdadeiro, os Profetas são verdadeiros, Muhammad ﷺ é verdadeiro e a Hora é verdadeira.", "No início da oração noturna (tahajjud), primeira parte da súplica.", "O Profeta ﷺ a recitava ao se levantar para o tahajjud (a súplica completa está em al-Bukhari)."),
        "dua_tahleel_10_fajr" to DuaText("Dez tahlil depois do Fajr e do Maghrib", "Não há divindade digna de adoração senão Allah, Único, sem associado. D'Ele é o domínio, a Ele pertence o louvor; Ele dá a vida e dá a morte, e Ele é capaz de todas as coisas.", "Dez vezes depois do Fajr (e do Maghrib), antes de sair do lugar ou falar.", "Dez boas ações, dez pecados apagados, dez graus elevados e proteção de Satanás o dia todo."),
        "dua_takbeer_tashreeq" to DuaText("O Takbir de Tashreeq", "Allah é o Maior, Allah é o Maior. Não há divindade senão Allah. Allah é o Maior, Allah é o Maior, e a Allah o louvor.", "Depois de cada oração obrigatória, do Fajr do dia 9 de Dhul-Hijjah até o Asr do dia 13 de Dhul-Hijjah.", "Relatado por Ali e Ibn Mas'ud (RA) — wajib segundo os Hanafitas."),
        "dua_talbiyah" to DuaText("A Talbiyah", "Aqui estou, ó Allah, aqui estou. Aqui estou, Tu não tens associado, aqui estou. A Ti pertencem o louvor, a graça e a soberania. Tu não tens associado.", "A ser dita em voz alta após entrar em ihram.", "O emblema do Hajj e da Umrah."),
        "dua_talqeen" to DuaText("O Talqin para o moribundo", "Ninguém tem o direito de ser adorado senão Allah.", "Recitar a kalima perto de uma pessoa moribunda (sem forçá-la a dizê-la).", "Aquele cujas últimas palavras são 'La ilaha illallah' entrará no Paraíso (Abu Dawud 3116)."),
        "dua_tashahhud" to DuaText("O Tashahhud (At-Tahiyyat)", "Todas as homenagens verbais, físicas e materiais pertencem a Allah. Que a paz esteja sobre ti, ó Profeta, assim como a misericórdia de Allah e Suas bênçãos. Que a paz esteja sobre nós e sobre os servos virtuosos de Allah. Testemunho que não há divindade senão Allah, e testemunho que Muhammad ﷺ é Seu servo e Mensageiro.", "Em cada posição sentada — relatado por Abdullah ibn Mas'ud (RA), prática dos Hanafitas.", "O Profeta ﷺ o ensinava como uma surata do Alcorão."),
        "dua_thabbitni_hadiyan" to DuaText("Torna-me firme, guia e guiado", "Ó Allah, torna-me firme, e faze de mim aquele que guia e é guiado.", "O Profeta ﷺ fez esta súplica por Jarir (RA) (para si mesmo, dizer 'thabbitni').", "A súplica original para Jarir (RA) usa as palavras 'thabbit-hu'."),
        "dua_thanking" to DuaText("Agradecer a alguém", "Que Allah te recompense com o bem.", "Quando alguém lhe presta um favor.", "Quem diz isso expressou plenamente sua gratidão."),
        "dua_thunder" to DuaText("Ao ouvir o trovão", "Glória a Quem o trovão glorifica com Seu louvor, assim como os anjos por temor a Ele.", "Ao ouvir o trovão — prática de Abdullah ibn az-Zubayr (RA).", "Extraído da surata ar-Ra'd (13:13)."),
        "dua_toilet_enter" to DuaText("Ao entrar no banheiro", "Em nome de Allah. Ó Allah, busco refúgio em Ti contra os gênios machos e fêmeas impuros.", "Antes de entrar no banheiro com o pé esquerdo.", "O Bismillah se torna um véu entre os gênios e a pessoa."),
        "dua_toilet_exit" to DuaText("Ao sair do banheiro", "(Ó Allah,) peço-Te perdão.", "Ao sair do banheiro com o pé direito.", "O Profeta ﷺ dizia isso ao sair do banheiro."),
        "dua_traveller_sahar" to DuaText("O viajante antes do amanhecer", "Um ouvinte ouviu (e relatou) nosso louvor a Allah e Seus favores para conosco. Nosso Senhor, acompanha-nos e concede-nos Teu favor — (digo isso) buscando refúgio em Allah contra o Fogo.", "Em viagem, antes do amanhecer.", "O Profeta ﷺ dizia isso antes do amanhecer em viagem."),
        "dua_traveller_to_resident" to DuaText("Do viajante para os que ficam", "Confio-te a Allah, junto a quem os depósitos nunca se perdem.", "Dito pelo viajante ao se despedir de sua família.", "Confiar a segurança da família a Allah."),
        "dua_two_light_words" to DuaText("Duas palavras leves na língua", "Glória a Allah e louvor a Ele; glória a Allah, o Magnífico.", "Leves na língua, pesadas na Balança.", "Amadas pelo Todo-Misericordioso, leves na língua e pesadas na Balança. (O último hadith de al-Bukhari)"),
        "dua_undressing" to DuaText("Ao se despir", "Em nome de Allah.", "Ao retirar as roupas (para o ghusl ou para se trocar).", "Isso se torna um véu entre os olhos dos gênios e as partes íntimas de uma pessoa."),
        "dua_useless_knowledge" to DuaText("Refúgio contra o conhecimento inútil", "Ó Allah, busco refúgio em Ti contra um conhecimento que não beneficia, um coração que não teme, uma alma nunca saciada, e uma súplica não atendida.", "Proteção contra o conhecimento inútil e um coração sem temor a Allah.", "Uma súplica de proteção do Profeta ﷺ."),
        "dua_vehicle_stumbles" to DuaText("Quando a montaria tropeça", "Em nome de Allah.", "Quando a montaria ou o veículo desliza ou tropeça, em vez de dizer 'que Satanás pereça'.", "Dizer Bismillah faz Satanás encolher ao tamanho de uma mosca."),
        "dua_visiting_graves" to DuaText("Visitar os túmulos", "Que a paz esteja sobre vós, ó crentes e muçulmanos habitantes destas moradas. Nós vos seguiremos, se Allah quiser. Peço a Allah o bem-estar para nós e para vós.", "Ao entrar no cemitério.", "Visitar os túmulos lembra a morte e o além."),
        "dua_waking_afani" to DuaText("Ao acordar: Ele restaurou minha alma", "Louvado seja Allah que devolveu a saúde ao meu corpo, restituiu minha alma e me permitiu recordá-Lo.", "Ao acordar.", "Gratidão por uma nova manhã."),
        "dua_waswasa_salah" to DuaText("Sugestões satânicas durante a oração (Khinzab)", "Busco refúgio em Allah contra Satanás, o amaldiçoado.", "Quando surgem sugestões satânicas durante a oração, buscar refúgio e cuspir levemente à esquerda três vezes.", "Uthman ibn Abil-'As (RA) fez isso e as sugestões desapareceram."),
        "dua_wedding_night" to DuaText("Pela esposa após o nikah", "Ó Allah, peço-Te seu bem e o bem da natureza com que a dotaste, e busco refúgio em Ti contra seu mal e o mal da natureza com que a dotaste.", "Depois do nikah, colocando a mão na testa da esposa.", "O ensinamento do Profeta ﷺ — bênção no casamento."),
        "dua_wind" to DuaText("Quando o vento sopra", "Ó Allah, peço-Te seu bem, o bem que ele contém e o bem daquilo para que foi enviado, e busco refúgio em Ti contra seu mal, o mal que ele contém e o mal daquilo para que foi enviado.", "Quando sopra um vento forte ou uma tempestade.", "O Profeta ﷺ fazia esta súplica durante as tempestades."),
        "dua_ya_dhal_jalal" to DuaText("Ó Detentor de Majestade e Honra", "Ó Detentor de Majestade e Honra!", "Apegar-se a isso na súplica — instrução do Profeta ﷺ.", "O Profeta ﷺ disse: apeguem-se a 'Ya Dhal-Jalali wal-Ikram'."),
        "dua_yamani_hajar" to DuaText("Entre o canto iemenita e a Pedra Negra", "Nosso Senhor, concede-nos o bem nesta vida e o bem na Outra, e protege-nos do castigo do Fogo.", "Durante o tawaf, entre o canto iemenita e a Pedra Negra.", "O Profeta ﷺ recitava isso neste ponto do tawaf."),
        "dua_zamzam" to DuaText("Ao beber a água de Zamzam", "Ó Allah, peço-Te conhecimento útil, sustento abundante e a cura de toda doença.", "Ao beber a água de Zamzam, suplicar pelo que se deseja.", "A água de Zamzam atende à intenção com que é bebida (Ibn Majah 3062)."),
        "dua_zawal_nimah" to DuaText("Refúgio contra a perda dos favores", "Ó Allah, busco refúgio em Ti contra o desaparecimento de Teus favores, a mudança da serenidade que me concedeste, Teu castigo repentino e tudo o que provoca Teu descontentamento.", "Proteção contra a perda dos favores e as desgraças repentinas.", "Uma súplica do Profeta ﷺ."),
        "dua_zawwadakallah" to DuaText("Despedida do viajante: que Allah te proveja de piedade", "Que Allah te proveja de piedade para tua viagem, te perdoe teus pecados e te facilite o bem onde quer que estejas.", "Ao se despedir de um viajante.", "O Profeta ﷺ fez esta súplica a alguém que partia em viagem.")
    )
}
